$-0.75-1.75=-2.50$

Align decimal places and preserve the sign.$mw$),
(821,1571,$mw$40195D6A02F8C3B62382AF4CB75C88459FC9D30372954E68AA63B89EDE017302$mw$,$mw$863f24c81e8974c45960da7fd5ca2744$mw$,$mw$$mw$,$mw${"Id":1571,"StageId":3,"CategoryId":86,"Points":10,"TitleAr":"يُعطى عدد أفراد مستعمرة بالدالة P(t)=250×(1.2)^t. ما P(2)؟","TitleEn":"A colony has P(t)=250×(1.2)^t. Find P(2).","QuestionTextAr":"يُعطى عدد أفراد مستعمرة بالدالة P(t)=250×(1.2)^t. ما P(2)؟","QuestionTextEn":"A colony has P(t)=250×(1.2)^t. Find P(2).","DetailedSolutionAr":"القانون المستخدم: النمو الأسّي P(t) = P₀ × g^t، حيث P₀ القيمة الابتدائية وg عامل النمو لكل فترة. لدينا P₀ = 250 وg = 1.2 وt = 2؛ نحسب 1.2² = 1.44، ثم P(2) = 250 × 1.44 = 360 فرداً. استعملنا عامل النمو مرتين لأن المدة فترتان.","DetailedSolutionEn":"Rule used: Exponential growth P(t) = P₀ g^t, where P₀ is initial population and g is the growth factor per period. Here P₀ = 250, g = 1.2 and t = 2. Compute 1.2² = 1.44, then P(2) = 250 × 1.44 = 360 individuals.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":6273,"Order":1,"LatexCode":"300","IsCorrect":false},{"Id":6274,"Order":2,"LatexCode":"360","IsCorrect":true},{"Id":6275,"Order":3,"LatexCode":"390","IsCorrect":false},{"Id":6276,"Order":4,"LatexCode":"250","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"حدد الكمية الابتدائية وعامل التغير لكل فترة.","En":"Identify the initial amount and the per-period multiplier."},{"Ar":"ارفع عامل التغير لعدد الفترات ثم اضرب في الكمية الابتدائية.","En":"Raise the multiplier to the number of periods, then multiply by the initial amount."}],"Title":{"Ar":"يُعطى عدد أفراد مستعمرة بالدالة P(t)=250×(1.2)^t. ما P(2)؟","En":"A colony has P(t)=250×(1.2)^t. Find P(2)."},"Points":10,"Options":[{"LatexCode":"300","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"300 قيمة P(1).","En":"300 is P(1)."}},{"LatexCode":"360","IsCorrect":true,"ErrorType":"","Reason":null},{"LatexCode":"390","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"390 لا يساوي 250×1.44.","En":"390 is not 250×1.44."}},{"LatexCode":"250","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"250 قيمة P(0).","En":"250 is P(0)."}}],"StageId":3,"Question":{"Ar":"يُعطى عدد أفراد مستعمرة بالدالة P(t)=250×(1.2)^t. ما P(2)؟","En":"A colony has P(t)=250×(1.2)^t. Find P(2)."},"Solution":{"Idea":{"Ar":"في النمو أو التناقص الأسي تتكرر عملية الضرب بالعامل نفسه في كل فترة.","En":"In exponential growth or decay, each period multiplies the amount by the same factor."},"Unit":{"Ar":"فرد","En":"Individuals"},"Steps":[{"Ar":"نعوض t=2 في النموذج.","En":"Substitute t=2 in the model."},{"Ar":"$P(2)=250(1.2)^2=250(1.44)$","En":"$P(2)=250(1.2)^2=250(1.44)$"},{"Ar":"نحسب مربع العامل ثم نضرب في الكمية الابتدائية.","En":"Square the factor and multiply by the initial amount."}],"Result":{"Ar":"$360$","En":"$360$"},"CommonError":{"Ar":"لا تضرب عامل النمو في عدد الفترات بدلاً من رفعه للأس.","En":"Do not multiply the growth factor by the period count instead of exponentiating it."},"FormulaLatex":"P(t)=250(1.2)^t","Substitution":{"Ar":"$360$","En":"$360$"},"Verification":{"Ar":"$250\\cdot1.2=300,\\quad300\\cdot1.2=360$","En":"$250\\cdot1.2=300,\\quad300\\cdot1.2=360$"}},"TrackIds":[11],"CategoryId":86,"PrimarySkillId":311,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"حدد الكمية الابتدائية وعامل التغير لكل فترة.","En":"Identify the initial amount and the per-period multiplier."},{"Ar":"ارفع عامل التغير لعدد الفترات ثم اضرب في الكمية الابتدائية.","En":"Raise the multiplier to the number of periods, then multiply by the initial amount."}],"Solution":{"Idea":{"Ar":"في النمو أو التناقص الأسي تتكرر عملية الضرب بالعامل نفسه في كل فترة.","En":"In exponential growth or decay, each period multiplies the amount by the same factor."},"Unit":{"Ar":"فرد","En":"Individuals"},"Steps":[{"Ar":"نعوض t=2 في النموذج.","En":"Substitute t=2 in the model."},{"Ar":"$P(2)=250(1.2)^2=250(1.44)$","En":"$P(2)=250(1.2)^2=250(1.44)$"},{"Ar":"نحسب مربع العامل ثم نضرب في الكمية الابتدائية.","En":"Square the factor and multiply by the initial amount."}],"Result":{"Ar":"$360$","En":"$360$"},"CommonError":{"Ar":"لا تضرب عامل النمو في عدد الفترات بدلاً من رفعه للأس.","En":"Do not multiply the growth factor by the period count instead of exponentiating it."},"FormulaLatex":"P(t)=250(1.2)^t","Substitution":{"Ar":"$360$","En":"$360$"},"Verification":{"Ar":"$250\\cdot1.2=300,\\quad300\\cdot1.2=360$","En":"$250\\cdot1.2=300,\\quad300\\cdot1.2=360$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"300 قيمة P(1).","En":"300 is P(1)."},"Order":1},{"ErrorType":"","Reason":null,"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"390 لا يساوي 250×1.44.","En":"390 is not 250×1.44."},"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"250 قيمة P(0).","En":"250 is P(0)."},"Order":4}]}$mw$,$mw$في النمو أو التناقص الأسي تتكرر عملية الضرب بالعامل نفسه في كل فترة.

$P(t)=250(1.2)^t$

1. نعوض t=2 في النموذج.

2. $P(2)=250(1.2)^2=250(1.44)$

3. نحسب مربع العامل ثم نضرب في الكمية الابتدائية.

$360$

$360$ فرد

$250\cdot1.2=300,\quad300\cdot1.2=360$

لا تضرب عامل النمو في عدد الفترات بدلاً من رفعه للأس.$mw$,$mw$In exponential growth or decay, each period multiplies the amount by the same factor.

$P(t)=250(1.2)^t$

1. Substitute t=2 in the model.

2. $P(2)=250(1.2)^2=250(1.44)$

3. Square the factor and multiply by the initial amount.

$360$

$360$ Individuals

$250\cdot1.2=300,\quad300\cdot1.2=360$

Do not multiply the growth factor by the period count instead of exponentiating it.$mw$),
(822,1572,$mw$F87C02D828C74172FF731C702E3527D92A83B89964F8BC6C7945664B7A0E5EB9$mw$,$mw$4c74cf2a3e23891dff854fc2f0affaa1$mw$,$mw$$mw$,$mw${"Id":1572,"StageId":3,"CategoryId":86,"Points":10,"TitleAr":"يبدأ عدد البكتيريا بـ80 ويتضاعف كل ساعة. كم يصبح بعد 3 ساعات؟","TitleEn":"A culture starts with 80 bacteria and doubles each hour. How many after 3 hours?","QuestionTextAr":"يبدأ عدد البكتيريا بـ80 ويتضاعف كل ساعة. كم يصبح بعد 3 ساعات؟","QuestionTextEn":"A culture starts with 80 bacteria and doubles each hour. How many after 3 hours?","DetailedSolutionAr":"القانون المستخدم: إذا تضاعفت كمية كل ساعة فإن عددها بعد t ساعات = العدد الابتدائي × 2^t. نبدأ بـ80 بكتيريا، وبعد 3 ساعات يكون عامل التضاعف 2³ = 8. إذن العدد = 80 × 8 = 640 بكتيريا. لا نضرب في 3 مباشرة لأن الزيادة مركبة.","DetailedSolutionEn":"Rule used: A quantity that doubles each hour follows N(t) = N₀ × 2^t. Starting with 80 bacteria and waiting 3 hours gives growth factor 2³ = 8. Therefore N(3) = 80 × 8 = 640 bacteria. Repeated doubling is exponential, not linear.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":6277,"Order":1,"LatexCode":"240","IsCorrect":false},{"Id":6278,"Order":2,"LatexCode":"320","IsCorrect":false},{"Id":6279,"Order":3,"LatexCode":"640","IsCorrect":true},{"Id":6280,"Order":4,"LatexCode":"480","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"حدد الكمية الابتدائية وعامل التغير لكل فترة.","En":"Identify the initial amount and the per-period multiplier."},{"Ar":"ارفع عامل التغير لعدد الفترات ثم اضرب في الكمية الابتدائية.","En":"Raise the multiplier to the number of periods, then multiply by the initial amount."}],"Title":{"Ar":"يبدأ عدد البكتيريا بـ80 ويتضاعف كل ساعة. كم يصبح بعد 3 ساعات؟","En":"A culture starts with 80 bacteria and doubles each hour. How many after 3 hours?"},"Points":10,"Options":[{"LatexCode":"240","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"240 يفترض نمواً خطياً لا تضاعفاً.","En":"240 assumes linear growth rather than doubling."}},{"LatexCode":"320","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"320 قيمة العدد بعد ساعتين.","En":"320 is the count after two hours."}},{"LatexCode":"640","IsCorrect":true,"ErrorType":"","Reason":null},{"LatexCode":"480","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"480 ليس ناتج ثلاثة تضاعفات.","En":"480 is not the result of three doublings."}}],"StageId":3,"Question":{"Ar":"يبدأ عدد البكتيريا بـ80 ويتضاعف كل ساعة. كم يصبح بعد 3 ساعات؟","En":"A culture starts with 80 bacteria and doubles each hour. How many after 3 hours?"},"Solution":{"Idea":{"Ar":"في النمو أو التناقص الأسي تتكرر عملية الضرب بالعامل نفسه في كل فترة.","En":"In exponential growth or decay, each period multiplies the amount by the same factor."},"Unit":{"Ar":"بكتيريا","En":"Bacteria"},"Steps":[{"Ar":"بعد ساعة يصبح العدد 160 وبعد ساعتين 320.","En":"After one hour the count is 160, after two it is 320."},{"Ar":"$N(3)=80\\cdot8$","En":"$N(3)=80\\cdot8$"},{"Ar":"نضاعف 320 مرة أخرى بعد الساعة الثالثة.","En":"Double 320 again after the third hour."}],"Result":{"Ar":"$640$","En":"$640$"},"CommonError":{"Ar":"اضرب في 2 كل ساعة.","En":"Multiply by two each hour."},"FormulaLatex":"N(t)=80\\cdot2^t","Substitution":{"Ar":"$640$","En":"$640$"},"Verification":{"Ar":"$640/2/2/2=80$","En":"$640/2/2/2=80$"}},"TrackIds":[11],"CategoryId":86,"PrimarySkillId":311,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"حدد الكمية الابتدائية وعامل التغير لكل فترة.","En":"Identify the initial amount and the per-period multiplier."},{"Ar":"ارفع عامل التغير لعدد الفترات ثم اضرب في الكمية الابتدائية.","En":"Raise the multiplier to the number of periods, then multiply by the initial amount."}],"Solution":{"Idea":{"Ar":"في النمو أو التناقص الأسي تتكرر عملية الضرب بالعامل نفسه في كل فترة.","En":"In exponential growth or decay, each period multiplies the amount by the same factor."},"Unit":{"Ar":"بكتيريا","En":"Bacteria"},"Steps":[{"Ar":"بعد ساعة يصبح العدد 160 وبعد ساعتين 320.","En":"After one hour the count is 160, after two it is 320."},{"Ar":"$N(3)=80\\cdot8$","En":"$N(3)=80\\cdot8$"},{"Ar":"نضاعف 320 مرة أخرى بعد الساعة الثالثة.","En":"Double 320 again after the third hour."}],"Result":{"Ar":"$640$","En":"$640$"},"CommonError":{"Ar":"اضرب في 2 كل ساعة.","En":"Multiply by two each hour."},"FormulaLatex":"N(t)=80\\cdot2^t","Substitution":{"Ar":"$640$","En":"$640$"},"Verification":{"Ar":"$640/2/2/2=80$","En":"$640/2/2/2=80$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"240 يفترض نمواً خطياً لا تضاعفاً.","En":"240 assumes linear growth rather than doubling."},"Order":1},{"ErrorType":"incorrect-option","Reason":{"Ar":"320 قيمة العدد بعد ساعتين.","En":"320 is the count after two hours."},"Order":2},{"ErrorType":"","Reason":null,"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"480 ليس ناتج ثلاثة تضاعفات.","En":"480 is not the result of three doublings."},"Order":4}]}$mw$,$mw$في النمو أو التناقص الأسي تتكرر عملية الضرب بالعامل نفسه في كل فترة.

$N(t)=80\cdot2^t$

1. بعد ساعة يصبح العدد 160 وبعد ساعتين 320.

2. $N(3)=80\cdot8$

3. نضاعف 320 مرة أخرى بعد الساعة الثالثة.

$640$

$640$ بكتيريا

$640/2/2/2=80$

اضرب في 2 كل ساعة.$mw$,$mw$In exponential growth or decay, each period multiplies the amount by the same factor.

$N(t)=80\cdot2^t$

1. After one hour the count is 160, after two it is 320.

2. $N(3)=80\cdot8$

3. Double 320 again after the third hour.

$640$

$640$ Bacteria

$640/2/2/2=80$

Multiply by two each hour.$mw$),
(823,1573,$mw$AED8A6792FEA50BCACAF4A92A6C9F9CC32BF608485BB250554C81605EEFA7493$mw$,$mw$5e70e3b9f9f7eddec73fe9496ced6a45$mw$,$mw$$mw$,$mw${"Id":1573,"StageId":3,"CategoryId":86,"Points":10,"TitleAr":"مبلغ 2,000 ينمو بمعدل 10% سنوياً دون سحب. كم يصبح بعد سنتين؟","TitleEn":"An amount of 2,000 grows by 10% each year. What is it after two years?","QuestionTextAr":"مبلغ 2,000 ينمو بمعدل 10% سنوياً دون سحب. كم يصبح بعد سنتين؟","QuestionTextEn":"An amount of 2,000 grows by 10% each year. What is it after two years?","DetailedSolutionAr":"القانون المستخدم: النمو المركب بمعدل r لكل سنة يعطى بالعلاقة A = A₀(1+r)^t. المبلغ الأولي 2,000 والمعدل 10% = 0.10 والسنتان t = 2. نحسب (1.10)² = 1.21، ثم A = 2,000 × 1.21 = 2,420. كل سنة تطبق الزيادة على القيمة الجديدة.","DetailedSolutionEn":"Rule used: Compound annual growth follows A = A₀(1+r)^t. With initial amount 2,000, annual rate r = 0.10 and t = 2, the multiplier is (1.10)² = 1.21. Thus A = 2,000 × 1.21 = 2,420. Each year's growth compounds on the updated amount.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":6281,"Order":1,"LatexCode":"2,200","IsCorrect":false},{"Id":6282,"Order":2,"LatexCode":"2,420","IsCorrect":true},{"Id":6283,"Order":3,"LatexCode":"2,400","IsCorrect":false},{"Id":6284,"Order":4,"LatexCode":"2,600","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"حدد الكمية الابتدائية وعامل التغير لكل فترة.","En":"Identify the initial amount and the per-period multiplier."},{"Ar":"ارفع عامل التغير لعدد الفترات ثم اضرب في الكمية الابتدائية.","En":"Raise the multiplier to the number of periods, then multiply by the initial amount."}],"Title":{"Ar":"مبلغ 2,000 ينمو بمعدل 10% سنوياً دون سحب. كم يصبح بعد سنتين؟","En":"An amount of 2,000 grows by 10% each year. What is it after two years?"},"Points":10,"Options":[{"LatexCode":"2,200","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"2200 قيمة السنة الأولى فقط.","En":"2200 is the first-year amount only."}},{"LatexCode":"2,420","IsCorrect":true,"ErrorType":"","Reason":null},{"LatexCode":"2,400","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"2400 يفترض زيادة ثابتة 200 كل سنة.","En":"2400 assumes a fixed increase of 200 per year."}},{"LatexCode":"2,600","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"2600 لا يساوي تطبيق عامل 1.1 مرتين.","En":"2600 is not obtained by applying 1.1 twice."}}],"StageId":3,"Question":{"Ar":"مبلغ 2,000 ينمو بمعدل 10% سنوياً دون سحب. كم يصبح بعد سنتين؟","En":"An amount of 2,000 grows by 10% each year. What is it after two years?"},"Solution":{"Idea":{"Ar":"في النمو أو التناقص الأسي تتكرر عملية الضرب بالعامل نفسه في كل فترة.","En":"In exponential growth or decay, each period multiplies the amount by the same factor."},"Unit":{"Ar":"وحدة نقدية","En":"Currency units"},"Steps":[{"Ar":"معدل 10% يعطي عامل 1.10 لكل سنة.","En":"A 10% rate gives factor 1.10 per year."},{"Ar":"$2000(1.1)^2$","En":"$2000(1.1)^2$"},{"Ar":"بعد السنة الأولى 2200؛ الزيادة الثانية 220 لأن النمو مركب.","En":"After year one there are 2200; the second increase is 220 because growth compounds."}],"Result":{"Ar":"$2{,}420$","En":"$2{,}420$"},"CommonError":{"Ar":"احسب الزيادة على المبلغ المتراكم لا الأصل وحده.","En":"Apply growth to the accumulated amount, not just the principal."},"FormulaLatex":"A=P(1+r)^t","Substitution":{"Ar":"$2420$","En":"$2420$"},"Verification":{"Ar":"$2200+220=2420$","En":"$2200+220=2420$"}},"TrackIds":[11],"CategoryId":86,"PrimarySkillId":311,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"حدد الكمية الابتدائية وعامل التغير لكل فترة.","En":"Identify the initial amount and the per-period multiplier."},{"Ar":"ارفع عامل التغير لعدد الفترات ثم اضرب في الكمية الابتدائية.","En":"Raise the multiplier to the number of periods, then multiply by the initial amount."}],"Solution":{"Idea":{"Ar":"في النمو أو التناقص الأسي تتكرر عملية الضرب بالعامل نفسه في كل فترة.","En":"In exponential growth or decay, each period multiplies the amount by the same factor."},"Unit":{"Ar":"وحدة نقدية","En":"Currency units"},"Steps":[{"Ar":"معدل 10% يعطي عامل 1.10 لكل سنة.","En":"A 10% rate gives factor 1.10 per year."},{"Ar":"$2000(1.1)^2$","En":"$2000(1.1)^2$"},{"Ar":"بعد السنة الأولى 2200؛ الزيادة الثانية 220 لأن النمو مركب.","En":"After year one there are 2200; the second increase is 220 because growth compounds."}],"Result":{"Ar":"$2{,}420$","En":"$2{,}420$"},"CommonError":{"Ar":"احسب الزيادة على المبلغ المتراكم لا الأصل وحده.","En":"Apply growth to the accumulated amount, not just the principal."},"FormulaLatex":"A=P(1+r)^t","Substitution":{"Ar":"$2420$","En":"$2420$"},"Verification":{"Ar":"$2200+220=2420$","En":"$2200+220=2420$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"2200 قيمة السنة الأولى فقط.","En":"2200 is the first-year amount only."},"Order":1},{"ErrorType":"","Reason":null,"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"2400 يفترض زيادة ثابتة 200 كل سنة.","En":"2400 assumes a fixed increase of 200 per year."},"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"2600 لا يساوي تطبيق عامل 1.1 مرتين.","En":"2600 is not obtained by applying 1.1 twice."},"Order":4}]}$mw$,$mw$في النمو أو التناقص الأسي تتكرر عملية الضرب بالعامل نفسه في كل فترة.

$A=P(1+r)^t$

1. معدل 10% يعطي عامل 1.10 لكل سنة.

2. $2000(1.1)^2$

3. بعد السنة الأولى 2200؛ الزيادة الثانية 220 لأن النمو مركب.

$2420$

$2{,}420$ وحدة نقدية

$2200+220=2420$

احسب الزيادة على المبلغ المتراكم لا الأصل وحده.$mw$,$mw$In exponential growth or decay, each period multiplies the amount by the same factor.

$A=P(1+r)^t$

1. A 10% rate gives factor 1.10 per year.

2. $2000(1.1)^2$

3. After year one there are 2200; the second increase is 220 because growth compounds.

$2420$

$2{,}420$ Currency units

$2200+220=2420$

Apply growth to the accumulated amount, not just the principal.$mw$),
(824,1574,$mw$4E5E64174DA5E9EC379229CAC274986E858342A433463B5A8998191E7720A9F2$mw$,$mw$b25a5eac1c4a56dc8e10c7c50f1edfb8$mw$,$mw$$mw$,$mw${"Id":1574,"StageId":3,"CategoryId":86,"Points":10,"TitleAr":"كم تبقى من 1,200 بعد تناقص 10% سنوياً لمدة سنتين؟","TitleEn":"How much remains of 1,200 after 10% decay each year for two years?","QuestionTextAr":"كم تبقى من 1,200 بعد تناقص 10% سنوياً لمدة سنتين؟","QuestionTextEn":"How much remains of 1,200 after 10% decay each year for two years?","DetailedSolutionAr":"القانون المستخدم: التناقص الأسّي بنسبة r سنوياً يكتب A = A₀(1−r)^t. البداية 1,200 ونسبة التناقص 10%، لذا عامل البقاء 0.90. بعد سنتين: A = 1,200 × 0.90² = 1,200 × 0.81 = 972. لا نطرح 20% خطياً لأن النقص في السنة الثانية من القيمة المتبقية.","DetailedSolutionEn":"Rule used: Repeated percentage decay follows A = A₀(1−r)^t. With A₀ = 1,200, r = 0.10 and t = 2, the retained factor is 0.90² = 0.81. The remaining amount is 1,200 × 0.81 = 972. The loss is compounded, not a single 20% subtraction.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":6285,"Order":1,"LatexCode":"960","IsCorrect":false},{"Id":6286,"Order":2,"LatexCode":"1,080","IsCorrect":false},{"Id":6287,"Order":3,"LatexCode":"972","IsCorrect":true},{"Id":6288,"Order":4,"LatexCode":"980","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"حدد الكمية الابتدائية وعامل التغير لكل فترة.","En":"Identify the initial amount and the per-period multiplier."},{"Ar":"ارفع عامل التغير لعدد الفترات ثم اضرب في الكمية الابتدائية.","En":"Raise the multiplier to the number of periods, then multiply by the initial amount."}],"Title":{"Ar":"كم تبقى من 1,200 بعد تناقص 10% سنوياً لمدة سنتين؟","En":"How much remains of 1,200 after 10% decay each year for two years?"},"Points":10,"Options":[{"LatexCode":"960","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"960 يفترض نقصاناً ثابتاً 120 كل سنة.","En":"960 assumes a fixed loss of 120 every year."}},{"LatexCode":"1,080","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"1080 قيمة السنة الأولى.","En":"1080 is the first-year amount."}},{"LatexCode":"972","IsCorrect":true,"ErrorType":"","Reason":null},{"LatexCode":"980","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"980 لا يساوي 1080×0.9.","En":"980 is not 1080×0.9."}}],"StageId":3,"Question":{"Ar":"كم تبقى من 1,200 بعد تناقص 10% سنوياً لمدة سنتين؟","En":"How much remains of 1,200 after 10% decay each year for two years?"},"Solution":{"Idea":{"Ar":"في النمو أو التناقص الأسي تتكرر عملية الضرب بالعامل نفسه في كل فترة.","En":"In exponential growth or decay, each period multiplies the amount by the same factor."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"تناقص 10% يبقي 90% من الكمية كل سنة.","En":"A 10% decay leaves 90% of the amount each year."},{"Ar":"$1200(0.9)^2$","En":"$1200(0.9)^2$"},{"Ar":"بعد السنة الأولى يبقى 1080؛ بعد الثانية نطرح 108 منه.","En":"After the first year 1080 remains; after the second subtract 108 from it."}],"Result":{"Ar":"$972$","En":"$972$"},"CommonError":{"Ar":"لا تطرح مقدار النقص الأول نفسه كل سنة.","En":"Do not subtract the same initial loss every year."},"FormulaLatex":"Q(t)=Q_0(1-r)^t","Substitution":{"Ar":"$972$","En":"$972$"},"Verification":{"Ar":"$1080-108=972$","En":"$1080-108=972$"}},"TrackIds":[11],"CategoryId":86,"PrimarySkillId":310,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"حدد الكمية الابتدائية وعامل التغير لكل فترة.","En":"Identify the initial amount and the per-period multiplier."},{"Ar":"ارفع عامل التغير لعدد الفترات ثم اضرب في الكمية الابتدائية.","En":"Raise the multiplier to the number of periods, then multiply by the initial amount."}],"Solution":{"Idea":{"Ar":"في النمو أو التناقص الأسي تتكرر عملية الضرب بالعامل نفسه في كل فترة.","En":"In exponential growth or decay, each period multiplies the amount by the same factor."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"تناقص 10% يبقي 90% من الكمية كل سنة.","En":"A 10% decay leaves 90% of the amount each year."},{"Ar":"$1200(0.9)^2$","En":"$1200(0.9)^2$"},{"Ar":"بعد السنة الأولى يبقى 1080؛ بعد الثانية نطرح 108 منه.","En":"After the first year 1080 remains; after the second subtract 108 from it."}],"Result":{"Ar":"$972$","En":"$972$"},"CommonError":{"Ar":"لا تطرح مقدار النقص الأول نفسه كل سنة.","En":"Do not subtract the same initial loss every year."},"FormulaLatex":"Q(t)=Q_0(1-r)^t","Substitution":{"Ar":"$972$","En":"$972$"},"Verification":{"Ar":"$1080-108=972$","En":"$1080-108=972$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"960 يفترض نقصاناً ثابتاً 120 كل سنة.","En":"960 assumes a fixed loss of 120 every year."},"Order":1},{"ErrorType":"incorrect-option","Reason":{"Ar":"1080 قيمة السنة الأولى.","En":"1080 is the first-year amount."},"Order":2},{"ErrorType":"","Reason":null,"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"980 لا يساوي 1080×0.9.","En":"980 is not 1080×0.9."},"Order":4}]}$mw$,$mw$في النمو أو التناقص الأسي تتكرر عملية الضرب بالعامل نفسه في كل فترة.

$Q(t)=Q_0(1-r)^t$

1. تناقص 10% يبقي 90% من الكمية كل سنة.

2. $1200(0.9)^2$

3. بعد السنة الأولى يبقى 1080؛ بعد الثانية نطرح 108 منه.

$972$

$972$ بلا وحدة قياس

$1080-108=972$

لا تطرح مقدار النقص الأول نفسه كل سنة.$mw$,$mw$In exponential growth or decay, each period multiplies the amount by the same factor.

$Q(t)=Q_0(1-r)^t$

1. A 10% decay leaves 90% of the amount each year.

2. $1200(0.9)^2$

3. After the first year 1080 remains; after the second subtract 108 from it.

$972$

$972$ Dimensionless

$1080-108=972$

Do not subtract the same initial loss every year.$mw$),
(825,1575,$mw$582E855BF122B7F107F5C9D2C0168E3563250F72C6FD3BCD7FF3F951BEC2EA34$mw$,$mw$519e58796f7b8a29b7c40494a9fd85d1$mw$,$mw$$mw$,$mw${"Id":1575,"StageId":3,"CategoryId":86,"Points":10,"TitleAr":"كتلة 640 غراماً ونصف عمرها 4 ساعات. بعد كم ساعة تصبح 80 غراماً؟","TitleEn":"A 640 g sample has a half-life of 4 hours. After how many hours will it reach 80 g?","QuestionTextAr":"كتلة 640 غراماً ونصف عمرها 4 ساعات. بعد كم ساعة تصبح 80 غراماً؟","QuestionTextEn":"A 640 g sample has a half-life of 4 hours. After how many hours will it reach 80 g?","DetailedSolutionAr":"القانون المستخدم: كمية المادة بعد زمن t مع عمر نصف h هي M(t) = M₀(1/2)^(t/h). من 640 غ إلى 80 غ تكون النسبة 80/640 = 1/8 = (1/2)³؛ إذن مرّت 3 أعمار نصف. كل عمر نصف 4 ساعات، لذلك الزمن = 3 × 4 = 12 ساعة.","DetailedSolutionEn":"Rule used: Half-life decay is M(t) = M₀(1/2)^(t/h), where h is the half-life. The target fraction is 80/640 = 1/8 = (1/2)³, so three half-lives pass. Each lasts 4 hours, giving t = 3 × 4 = 12 hours.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":6289,"Order":1,"LatexCode":"8","IsCorrect":false},{"Id":6290,"Order":2,"LatexCode":"16","IsCorrect":false},{"Id":6291,"Order":3,"LatexCode":"12","IsCorrect":true},{"Id":6292,"Order":4,"LatexCode":"20","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"احسب عدد مرات التنصيف اللازمة.","En":"Find the number of halvings required."},{"Ar":"حدد عدد أنصاف الأعمار ثم اضربه بزمن نصف العمر.","En":"Find the number of half-lives, then multiply by the half-life duration."}],"Title":{"Ar":"كتلة 640 غراماً ونصف عمرها 4 ساعات. بعد كم ساعة تصبح 80 غراماً؟","En":"A 640 g sample has a half-life of 4 hours. After how many hours will it reach 80 g?"},"Points":10,"Options":[{"LatexCode":"8","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"8 ساعات تعطي 160 غراماً.","En":"Eight hours leaves 160 grams."}},{"LatexCode":"16","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"16 ساعة تعطي 40 غراماً.","En":"Sixteen hours leaves 40 grams."}},{"LatexCode":"12","IsCorrect":true,"ErrorType":"","Reason":null},{"LatexCode":"20","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"20 ساعة تعطي 20 غراماً.","En":"Twenty hours leaves 20 grams."}}],"StageId":3,"Question":{"Ar":"كتلة 640 غراماً ونصف عمرها 4 ساعات. بعد كم ساعة تصبح 80 غراماً؟","En":"A 640 g sample has a half-life of 4 hours. After how many hours will it reach 80 g?"},"Solution":{"Idea":{"Ar":"نصف العمر هو الزمن اللازم لانخفاض الكمية إلى نصفها.","En":"Half-life is the time needed for an amount to halve."},"Unit":{"Ar":"ساعة","En":"Hours"},"Steps":[{"Ar":"تنخفض الكتلة بالترتيب من 640 إلى 320 ثم 160 ثم 80.","En":"The mass decreases from 640 to 320, then 160, then 80."},{"Ar":"$640/80=8=2^3$","En":"$640/80=8=2^3$"},{"Ar":"ثلاثة أنصاف أعمار، مدة كل واحد أربع ساعات.","En":"There are three half-lives, each four hours."}],"Result":{"Ar":"$12$","En":"$12$"},"CommonError":{"Ar":"ميز عدد أنصاف الأعمار عن الزمن بالساعات.","En":"Distinguish number of half-lives from elapsed hours."},"FormulaLatex":"m(t)=640(1/2)^{t/4}","Substitution":{"Ar":"$t=3\\cdot4=12$","En":"$t=3\\cdot4=12$"},"Verification":{"Ar":"$640(1/2)^3=80$","En":"$640(1/2)^3=80$"}},"TrackIds":[12],"CategoryId":86,"PrimarySkillId":310,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"احسب عدد مرات التنصيف اللازمة.","En":"Find the number of halvings required."},{"Ar":"حدد عدد أنصاف الأعمار ثم اضربه بزمن نصف العمر.","En":"Find the number of half-lives, then multiply by the half-life duration."}],"Solution":{"Idea":{"Ar":"نصف العمر هو الزمن اللازم لانخفاض الكمية إلى نصفها.","En":"Half-life is the time needed for an amount to halve."},"Unit":{"Ar":"ساعة","En":"Hours"},"Steps":[{"Ar":"تنخفض الكتلة بالترتيب من 640 إلى 320 ثم 160 ثم 80.","En":"The mass decreases from 640 to 320, then 160, then 80."},{"Ar":"$640/80=8=2^3$","En":"$640/80=8=2^3$"},{"Ar":"ثلاثة أنصاف أعمار، مدة كل واحد أربع ساعات.","En":"There are three half-lives, each four hours."}],"Result":{"Ar":"$12$","En":"$12$"},"CommonError":{"Ar":"ميز عدد أنصاف الأعمار عن الزمن بالساعات.","En":"Distinguish number of half-lives from elapsed hours."},"FormulaLatex":"m(t)=640(1/2)^{t/4}","Substitution":{"Ar":"$t=3\\cdot4=12$","En":"$t=3\\cdot4=12$"},"Verification":{"Ar":"$640(1/2)^3=80$","En":"$640(1/2)^3=80$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"8 ساعات تعطي 160 غراماً.","En":"Eight hours leaves 160 grams."},"Order":1},{"ErrorType":"incorrect-option","Reason":{"Ar":"16 ساعة تعطي 40 غراماً.","En":"Sixteen hours leaves 40 grams."},"Order":2},{"ErrorType":"","Reason":null,"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"20 ساعة تعطي 20 غراماً.","En":"Twenty hours leaves 20 grams."},"Order":4}]}$mw$,$mw$نصف العمر هو الزمن اللازم لانخفاض الكمية إلى نصفها.

$m(t)=640(1/2)^{t/4}$

1. تنخفض الكتلة بالترتيب من 640 إلى 320 ثم 160 ثم 80.

2. $640/80=8=2^3$

3. ثلاثة أنصاف أعمار، مدة كل واحد أربع ساعات.

$t=3\cdot4=12$

$12$ ساعة

$640(1/2)^3=80$

ميز عدد أنصاف الأعمار عن الزمن بالساعات.$mw$,$mw$Half-life is the time needed for an amount to halve.

$m(t)=640(1/2)^{t/4}$

1. The mass decreases from 640 to 320, then 160, then 80.

2. $640/80=8=2^3$

3. There are three half-lives, each four hours.

$t=3\cdot4=12$

$12$ Hours

$640(1/2)^3=80$

Distinguish number of half-lives from elapsed hours.$mw$),
(829,1585,$mw$691B2DDAB1A94F65FCCCAE29C512B07856013ACFE07A952DA3C1ED171FF2699C$mw$,$mw$5ba31f11a2ae3cb70d377c021b330ed3$mw$,$mw$$mw$,$mw${"Id":1585,"StageId":4,"CategoryId":89,"Points":10,"TitleAr":"عندما p=0.02 ومستوى الدلالة α=0.05، أي مقارنة تبرر رفض الفرضية الصفرية؟","TitleEn":"When p=0.02 and significance level α=0.05, which inequality justifies rejecting the null hypothesis?","QuestionTextAr":"عندما p=0.02 ومستوى الدلالة α=0.05، أي مقارنة تبرر رفض الفرضية الصفرية؟","QuestionTextEn":"When p=0.02 and significance level α=0.05, which inequality justifies rejecting the null hypothesis?","DetailedSolutionAr":"القانون المستخدم: في اختبار الفرضيات نرفض الفرضية الصفرية H₀ إذا كانت قيمة p أقل من أو تساوي مستوى الدلالة المحدد α، وفق قاعدة القرار المعتمدة. هنا p = 0.02 وα = 0.05، وبما أن 0.02 < 0.05 فإن العلاقة الدالة على الرفض هي p < α.","DetailedSolutionEn":"Rule used: For a standard p-value hypothesis test, reject the null hypothesis when the observed p-value is at or below the chosen significance level α. Here p = 0.02 and α = 0.05; since 0.02 < 0.05, the required inequality is p < α.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":6329,"Order":1,"LatexCode":"p>\\alpha","IsCorrect":false},{"Id":6330,"Order":2,"LatexCode":"p<\\alpha","IsCorrect":true},{"Id":6331,"Order":3,"LatexCode":"p=\\alpha","IsCorrect":false},{"Id":6332,"Order":4,"LatexCode":"p=1","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"قارن قيمة $p$ بعتبة الدلالة المحددة قبل الاختبار.","En":"Compare the p-value with the significance threshold set before the test."},{"Ar":"اكتب العددين بوحدة الأجزاء من مئة، ثم اختر إشارة المقارنة التي تصف ترتيبهما.","En":"Express both decimals in hundredths, then choose the comparison sign that describes their order."}],"Title":{"Ar":"عندما p=0.02 ومستوى الدلالة α=0.05، أي مقارنة تبرر رفض الفرضية الصفرية؟","En":"When p=0.02 and significance level α=0.05, which inequality justifies rejecting the null hypothesis?"},"Points":10,"Options":[{"LatexCode":"p>\\alpha","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"p ليست أكبر من α.","En":"p is not greater than alpha."}},{"LatexCode":"p<\\alpha","IsCorrect":true,"ErrorType":"","Reason":null},{"LatexCode":"p=\\alpha","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"القيمتان غير متساويتين.","En":"The values are unequal."}},{"LatexCode":"p=1","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"p تساوي 0.02 لا 1.","En":"p equals 0.02, not one."}}],"StageId":4,"Question":{"Ar":"عندما p=0.02 ومستوى الدلالة α=0.05، أي مقارنة تبرر رفض الفرضية الصفرية؟","En":"When p=0.02 and significance level α=0.05, which inequality justifies rejecting the null hypothesis?"},"Solution":{"Idea":{"Ar":"في اختبار القيمة الاحتمالية نقارن p بمستوى الدلالة.","En":"A p-value test compares p with the significance level."},"Unit":{"Ar":"بلا وحدة محددة","En":"No specified unit"},"Steps":[{"Ar":"القيمة الاحتمالية 2 من مئة ومستوى الدلالة 5 من مئة.","En":"The p-value is two hundredths and the significance level five hundredths."},{"Ar":"$0.02<0.05$","En":"$0.02<0.05$"},{"Ar":"بما أن الأولى أصغر، نرفض الفرضية الصفرية وفق قاعدة الاختبار عند تحقق افتراضاته.","En":"Since the first is smaller, reject the null under the test rule and its assumptions."}],"Result":{"Ar":"$p<\\alpha$","En":"$p<\\alpha$"},"CommonError":{"Ar":"لا تفسر p على أنها احتمال صحة الفرضية الصفرية.","En":"Do not interpret p as the probability that the null is true."},"FormulaLatex":"p<\\alpha","Substitution":{"Ar":"$p<\\alpha$","En":"$p<\\alpha$"},"Verification":{"Ar":"$\\alpha-p=0.03>0$","En":"$\\alpha-p=0.03>0$"}},"TrackIds":[16,21],"CategoryId":89,"PrimarySkillId":318,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"قارن قيمة $p$ بعتبة الدلالة المحددة قبل الاختبار.","En":"Compare the p-value with the significance threshold set before the test."},{"Ar":"اكتب العددين بوحدة الأجزاء من مئة، ثم اختر إشارة المقارنة التي تصف ترتيبهما.","En":"Express both decimals in hundredths, then choose the comparison sign that describes their order."}],"Solution":{"Idea":{"Ar":"في اختبار القيمة الاحتمالية نقارن p بمستوى الدلالة.","En":"A p-value test compares p with the significance level."},"Unit":{"Ar":"بلا وحدة محددة","En":"No specified unit"},"Steps":[{"Ar":"القيمة الاحتمالية 2 من مئة ومستوى الدلالة 5 من مئة.","En":"The p-value is two hundredths and the significance level five hundredths."},{"Ar":"$0.02<0.05$","En":"$0.02<0.05$"},{"Ar":"بما أن الأولى أصغر، نرفض الفرضية الصفرية وفق قاعدة الاختبار عند تحقق افتراضاته.","En":"Since the first is smaller, reject the null under the test rule and its assumptions."}],"Result":{"Ar":"$p<\\alpha$","En":"$p<\\alpha$"},"CommonError":{"Ar":"لا تفسر p على أنها احتمال صحة الفرضية الصفرية.","En":"Do not interpret p as the probability that the null is true."},"FormulaLatex":"p<\\alpha","Substitution":{"Ar":"$p<\\alpha$","En":"$p<\\alpha$"},"Verification":{"Ar":"$\\alpha-p=0.03>0$","En":"$\\alpha-p=0.03>0$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"p ليست أكبر من α.","En":"p is not greater than alpha."},"Order":1},{"ErrorType":"","Reason":null,"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"القيمتان غير متساويتين.","En":"The values are unequal."},"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"p تساوي 0.02 لا 1.","En":"p equals 0.02, not one."},"Order":4}]}$mw$,$mw$في اختبار القيمة الاحتمالية نقارن p بمستوى الدلالة.

$p<\alpha$

1. القيمة الاحتمالية 2 من مئة ومستوى الدلالة 5 من مئة.

2. $0.02<0.05$

3. بما أن الأولى أصغر، نرفض الفرضية الصفرية وفق قاعدة الاختبار عند تحقق افتراضاته.

$p<\alpha$

$p<\alpha$ بلا وحدة محددة

$\alpha-p=0.03>0$

لا تفسر p على أنها احتمال صحة الفرضية الصفرية.$mw$,$mw$A p-value test compares p with the significance level.

$p<\alpha$

1. The p-value is two hundredths and the significance level five hundredths.

2. $0.02<0.05$

3. Since the first is smaller, reject the null under the test rule and its assumptions.

$p<\alpha$

$p<\alpha$ No specified unit

$\alpha-p=0.03>0$

Do not interpret p as the probability that the null is true.$mw$);
DO $audit$
DECLARE b record; d "CurriculumDraftItems"%ROWTYPE; p "Problems"%ROWTYPE; tr int; sk int; n int; actor int;
BEGIN
 FOR b IN SELECT * FROM reviewed_batch ORDER BY source LOOP
  PERFORM pg_advisory_xact_lock(-b.source::bigint);
  SELECT * INTO STRICT d FROM "CurriculumDraftItems" WHERE "Id"=b.draft FOR UPDATE;
  SELECT * INTO STRICT p FROM "Problems" WHERE "Id"=b.source FOR UPDATE;
  PERFORM 1 FROM "QuestionOptions" WHERE "ProblemId"=b.source FOR UPDATE;
  actor:=d."OwnerUserId"; tr:=(b.wizard->'TrackIds'->>0)::int; sk:=(b.wizard->>'PrimarySkillId')::int;
  IF d."SourceProblemId" IS DISTINCT FROM b.source OR d."Revision"<>0 OR d."EditorialStatus"<>'Draft' OR d."PublishedProblemId" IS NOT NULL OR d."SourceFingerprint" IS DISTINCT FROM b.fp OR md5(d."WizardJson") IS DISTINCT FROM b.draft_hash OR upper(encode(sha256(decode(b.source_hex,'hex')),'hex'))<>b.fp OR (SELECT json_build_object('Id',pp."Id",'StageId',pp."StageId",'CategoryId',pp."CategoryId",'Points',pp."Points",'TitleAr',pp."TitleAr",'TitleEn',pp."TitleEn",'QuestionTextAr',pp."QuestionTextAr",'QuestionTextEn',pp."QuestionTextEn",'DetailedSolutionAr',pp."DetailedSolutionAr",'DetailedSolutionEn',pp."DetailedSolutionEn",'YoutubeSolutionUrl',pp."YoutubeSolutionUrl",'EditorialDetailsJson',pp."EditorialDetailsJson",'Options',(select json_agg(json_build_object('Id',o."Id",'Order',o."Order",'LatexCode',o."LatexCode",'IsCorrect',o."IsCorrect") order by o."Order",o."Id") from "QuestionOptions" o where o."ProblemId"=pp."Id"))::jsonb FROM "Problems" pp WHERE pp."Id"=b.source) IS DISTINCT FROM b.snapshot THEN RAISE EXCEPTION 'Source/draft conflict: %',b.draft; END IF;
  IF NOT EXISTS(SELECT 1 FROM "Users" WHERE "Id"=actor AND "Role"='Admin' AND "IsActive" AND NOT "StaffSetupPending") OR (SELECT count(*) FROM "CurriculumDraftItems" WHERE "SourceProblemId"=b.source AND "EditorialStatus" NOT IN ('Published','Withdrawn'))<>1 THEN RAISE EXCEPTION 'Owner/open-draft conflict: %',b.draft; END IF;
  PERFORM 1 FROM "LearningTracks" WHERE "Id" IN (SELECT jsonb_array_elements_text(b.wizard->'TrackIds')::int) ORDER BY "Id" FOR UPDATE;
  IF NOT EXISTS(SELECT 1 FROM "LearningTracks" WHERE "Id"=tr AND "StageId"=p."StageId" AND "IsPublished" AND "Revision"<2147483647) OR NOT EXISTS(SELECT 1 FROM "Categories" WHERE "Id"=p."CategoryId" AND "StageId"=p."StageId") OR NOT EXISTS(SELECT 1 FROM "CurriculumSkills" s JOIN "CurriculumDomains" dm ON dm."Id"=s."DomainId" WHERE s."Id"=sk AND s."StageId"=p."StageId" AND s."CategoryId"=p."CategoryId" AND s."IsPublished" AND dm."IsPublished") OR NOT EXISTS(SELECT 1 FROM "LearningTrackCategories" WHERE "TrackId"=tr AND "CategoryId"=p."CategoryId") OR NOT EXISTS(SELECT 1 FROM "LearningTrackSkills" WHERE "TrackId"=tr AND "SkillId"=sk) OR (SELECT array_agg("TrackId" ORDER BY "TrackId") FROM "LearningTrackProblems" WHERE "ProblemId"=b.source) IS DISTINCT FROM ARRAY(SELECT jsonb_array_elements_text(b.wizard->'TrackIds')::int ORDER BY 1) OR (SELECT array_agg("SkillId" ORDER BY "SkillId") FROM "CurriculumProblemSkills" WHERE "ProblemId"=b.source) IS DISTINCT FROM ARRAY[sk] OR NOT EXISTS(SELECT 1 FROM "CurriculumProblemSkills" WHERE "ProblemId"=b.source AND "SkillId"=sk AND "IsPrimary") OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(b.wizard->'TrackIds') j(id) LEFT JOIN "LearningTracks" lt ON lt."Id"=j.id::int WHERE lt."Id" IS NULL OR lt."StageId"<>p."StageId" OR lt."Revision">=2147483647 OR NOT EXISTS(SELECT 1 FROM "LearningTrackCategories" WHERE "TrackId"=lt."Id" AND "CategoryId"=p."CategoryId") OR NOT EXISTS(SELECT 1 FROM "LearningTrackSkills" WHERE "TrackId"=lt."Id" AND "SkillId"=sk)) THEN RAISE EXCEPTION 'Scope conflict: %',b.draft; END IF;
  IF EXISTS(SELECT 1 FROM "Problems" q WHERE q."Id"<>b.source AND q."StageId"=p."StageId" AND (upper(regexp_replace(btrim(q."QuestionTextAr"),'[[:space:]]+',' ','g'))=upper(regexp_replace(btrim(p."QuestionTextAr"),'[[:space:]]+',' ','g')) OR upper(regexp_replace(btrim(q."QuestionTextEn"),'[[:space:]]+',' ','g'))=upper(regexp_replace(btrim(p."QuestionTextEn"),'[[:space:]]+',' ','g')))) THEN RAISE EXCEPTION 'Duplicate: %',b.draft; END IF;
  IF EXISTS(SELECT 1 FROM "CurriculumDraftItems" x WHERE x."Id"<>b.draft AND x."EditorialStatus" NOT IN ('Published','Withdrawn') AND (x."WizardJson"::jsonb#>>'{Question,Ar}'=p."QuestionTextAr" OR x."WizardJson"::jsonb#>>'{Question,En}'=p."QuestionTextEn")) THEN RAISE EXCEPTION 'Open draft duplicate: %',b.draft; END IF;
  IF b.wizard#>>'{Question,Ar}' IS DISTINCT FROM p."QuestionTextAr" OR b.wizard#>>'{Question,En}' IS DISTINCT FROM p."QuestionTextEn" OR length(b.flat_ar)>12000 OR length(b.flat_en)>12000 THEN RAISE EXCEPTION 'Question/length conflict: %',b.draft; END IF;
  UPDATE "Problems" SET "TitleAr"=b.wizard#>>'{Title,Ar}',"TitleEn"=b.wizard#>>'{Title,En}',"DetailedSolutionAr"=b.flat_ar,"DetailedSolutionEn"=b.flat_en,"EditorialDetailsJson"=b.metadata WHERE "Id"=b.source;
  UPDATE "CurriculumDraftItems" SET "WizardJson"=b.wizard::text,"EditorialStatus"='Published',"Revision"=4,"SubmittedAtUtc"=now(),"ReviewedAtUtc"=now(),"ReviewedByUserId"=actor,"ReviewNote"='Owner-authorized SQL maintenance; AI educational review and source-locked verification. Existing draft owner recorded for attribution; no API login.',"PublishedAtUtc"=now(),"PublishedProblemId"=b.source WHERE "Id"=b.draft;
  UPDATE "LearningTracks" SET "Revision"="Revision"+1 WHERE "Id" IN (SELECT jsonb_array_elements_text(b.wizard->'TrackIds')::int);
  INSERT INTO "PlatformActivityEvents"("ActorUserId","ActorRole","Action","Resource","ResourceId","Origin","CreatedAtUtc") SELECT actor,'Admin',action,'EditorialProblem',b.draft::text,'owner_sql',now() FROM unnest(ARRAY['EditorialDraftEdited','EditorialDraftSubmitted','EditorialDraftApproved','EditorialAmendmentPublished']) action;
 END LOOP;
END $audit$;
COMMIT;
